const SYNTAX = /^sl-(noun|verb|adj|adv|conj)$/;

// What covers the caret or selection: flags, sentence, paragraph.
function describeAt(a, from, to) {
  const hit = a.hits.filter((h) => (from === to ? h.from <= from && h.to >= from : h.to > from && h.from < to));
  const sent = a.sents.find((x) => x.from <= to && x.to >= from);
  const para = a.paras.find((p) => p.from <= to && p.to >= from);
  return {
    tags: [...new Set(hit.filter((h) => SYNTAX.test(h.cls)).map((h) => h.cls))],
    flags: [...new Set(hit.filter((h) => !SYNTAX.test(h.cls)).map((h) => h.cls))],
    sent, para,
  };
}

