// Essay or story? Naive Bayes over six numbers, using the means and spreads in the two profiles.
const DETECT = ["pastPct", "thirdPct", "secondPct", "dialogueParaPct", "grade", "rate:sl-filter"];
function classify(a, profiles) {
  const w = a.stats.words;
  if (w < 150 || !profiles.essay || !profiles.story) return null;
  const vals = { pastPct: a.stats.pastPct, thirdPct: a.stats.thirdPct, secondPct: a.stats.secondPct, dialogueParaPct: a.stats.dialogueParaPct, grade: a.stats.grade, "rate:sl-filter": ((a.counts["sl-filter"] || 0) * 1000) / w };
  const ll = { essay: 0, story: 0 };
  for (const k of DETECT) for (const lab of ["essay", "story"]) {
    const m = profiles[lab].metrics[k];
    if (!m || m.sd == null) return null;
    const sd = Math.max(m.sd, 0.3);
    ll[lab] += -Math.log(sd) - (vals[k] - m.mean) ** 2 / (2 * sd * sd);
  }
  const pStory = 1 / (1 + Math.exp(-Math.max(-30, Math.min(30, ll.story - ll.essay))));
  return { label: pStory >= 0.5 ? "story" : "essay", p: Math.max(pStory, 1 - pStory) };
}
